export const meta = {
  name: 'skf-queue-validate',
  description: 'Re-validate SKF improvement-queue findings against current source, design fixes, adversarially verify',
  phases: [
    { title: 'Validate & Design' },
    { title: 'Adversarial Verify' },
  ],
}

const REPO = '/home/armel/Projects/OSS/bmad-module-skill-forge'
const PERRY = '/home/armel/Projects/Starter/perry-starter/forge-data/improvement-queue'
const GMC = '/home/armel/Projects/GMC/Code/gmc-skills/forge-data/improvement-queue'

const CONVENTIONS = `
SKF repo conventions you MUST respect when designing a fix (violating these breaks CI):
- Step files are prose instructions (.md) read by an LLM at runtime; "fixing" one means editing the prose/branches/probe-orders, not code.
- Python helpers live at src/shared/scripts/*.py and have pytest suites at test/test-<name>.py (enumerated in package.json "test:python").
- SKILL.md heading vocabulary is gated by validate-output (substring) AND a scanner (exact full-text) that must agree — do NOT rename headings; widen synonyms if needed.
- validate:refs (tools/validate-file-refs.js --strict) resolves file paths written in prose under src/; do NOT write "{project-root}/_bmad/custom/..." in prose — use bare "_bmad/custom/<name>" phrasing.
- Never hand-edit CHANGELOG.md (release-managed). No inline version-stamp markers (vX.Y.Z) in docs.
- Python cross-platform rules: POSIX-form path assertions (Path.as_posix), byte-exact writes need O_BINARY, read non-ASCII with encoding="utf-8".
- A fix that adds a new probe-order path or branch must keep existing paths working (additive, not replacing).
`

const VALIDATION_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['id', 'verdict', 'verdict_reasoning', 'current_source_evidence', 'root_cause_location', 'fix_type', 'proposed_fix', 'files_to_edit', 'collateral_impacts', 'test_coverage', 'breaking_change_risk', 'breaking_change_reasoning', 'confidence'],
  properties: {
    id: { type: 'string' },
    verdict: { type: 'string', enum: ['STILL_VALID', 'ALREADY_FIXED', 'FALSE_POSITIVE', 'PARTIALLY_VALID', 'NEEDS_REFRAMING'] },
    verdict_reasoning: { type: 'string' },
    current_source_evidence: { type: 'string', description: 'Quote the ACTUAL current lines you read (with file:line), proving the finding is or is not still present. Do not trust the finding line numbers blindly.' },
    root_cause_location: { type: 'string' },
    fix_type: { type: 'string', enum: ['step_file_edit', 'python_script_edit', 'both', 'none'] },
    proposed_fix: { type: 'string', description: 'Precise fix. For edits give exact old-text -> new-text snippets that will actually match the file.' },
    files_to_edit: { type: 'array', items: { type: 'string' } },
    collateral_impacts: { type: 'string', description: 'Other files referencing the same pattern that must change too; tests to add/update; heading-gate / validate:refs / schema concerns.' },
    test_coverage: { type: 'string', description: 'Existing tests covering this; whether they would catch a regression; whether a new test is warranted.' },
    breaking_change_risk: { type: 'string', enum: ['none', 'low', 'medium', 'high'] },
    breaking_change_reasoning: { type: 'string' },
    confidence: { type: 'string', enum: ['low', 'medium', 'high'] },
  },
}

const VERIFY_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['id', 'fix_is_correct', 'fix_is_complete', 'would_break_something', 'refutation', 'missed_files', 'missed_tests', 'corrected_fix', 'final_recommendation'],
  properties: {
    id: { type: 'string' },
    fix_is_correct: { type: 'boolean' },
    fix_is_complete: { type: 'boolean' },
    would_break_something: { type: 'boolean' },
    refutation: { type: 'string', description: 'Strongest argument the proposed fix is wrong/incomplete/breaking, grounded in files you actually read. "none found" only after a real attempt.' },
    missed_files: { type: 'array', items: { type: 'string' } },
    missed_tests: { type: 'array', items: { type: 'string' } },
    corrected_fix: { type: 'string', description: 'If the fix needs adjustment, the corrected version; else "use original".' },
    final_recommendation: { type: 'string', enum: ['APPLY_AS_IS', 'APPLY_WITH_CHANGES', 'DO_NOT_APPLY', 'DEFER'] },
  },
}

const findings = [
  {
    id: 'export-probe-order', severity: 'bug',
    file: `${PERRY}/hc-skf-export-skill-20260628-124635-fp-0b9e4ec.md`,
    sources: ['src/skf-export-skill/references/update-context.md', 'src/skf-export-skill/SKILL.md'],
    hint: 'Finding claims probe orders + On-Activation config load only consider _bmad/skf/ and src/ roots, with no .claude/skills/ candidate, causing a false HALT on a .claude/skills/-rooted install. VERIFY: does the current update-context.md probe-order block actually omit a .claude/skills/ entry? Check how OTHER skf skills / shared preflight-snippet-root-probe.md handle root resolution — is there a canonical root-probe pattern this should reuse rather than hardcoding?',
  },
  {
    id: 'export-all-flat-layout', severity: 'gap',
    file: `${PERRY}/hc-skf-export-skill-20260628-124635-fp-c94df25.md`,
    sources: ['src/skf-export-skill/references/load-skill.md', 'src/skf-export-skill/references/update-context.md'],
    hint: 'Finding claims (a) --all is defined only against .export-manifest.json.exports so a first-ever --all export on a fresh repo has nothing to enumerate, and (b) §4c resolves context-snippet.md only at versioned path skills/<name>/<version>/<name>/context-snippet.md, skipping flat-layout skills/<name>/SKILL.md. VERIFY current load-skill.md §1 and update-context.md §4b/§4c. Check if a directory-discovery fallback already exists.',
  },
  {
    id: 'setup-first-run-banner', severity: 'gap',
    file: `${PERRY}/hc-skf-setup-20260622-181935-fp-4a59d3f.md`,
    sources: ['src/skf-setup/references/report.md', 'src/skf-setup/references/detect-and-tier.md'],
    hint: 'Finding claims report.md delta-message Branch 3 (tier_changed false and tools_added/removed non-empty) is unguarded and fires on first run (previous_tier null), printing "Tier unchanged" instead of an initial-detection banner. VERIFY the current branch guards in report.md and the first-run detector output in detect-and-tier.md.',
  },
  {
    id: 'setup-ccc-version-parse', severity: 'friction',
    file: `${PERRY}/hc-skf-setup-20260622-181935-fp-852fd7d.md`,
    sources: ['src/skf-setup/references/report.md', 'src/shared/scripts/skf-detect-tools.py'],
    hint: 'Finding claims ccc detected version is a misparsed header "Global Settings", so report.md rule "tool name — version" prints nonsense. Root cause likely skf-detect-tools.py ccc version parse. VERIFY: how does skf-detect-tools.py currently parse the ccc version? Reproduce what `ccc` CLI output looks like if possible (check the parse regex/logic). Decide: fix the parser, or fix report.md fallback, or both. There is test/test-skf-detect-tools.py.',
  },
  {
    id: 'validate-pins-dot-repo', severity: 'bug',
    file: `${PERRY}/perry-starter-impl-findings.md`,
    sources: ['src/shared/scripts/skf-validate-pins.py'],
    hint: 'Finding: _GITHUB_URL_RE uses ([^/\\s.]+?) for the repo segment, rejecting repo names containing a dot (e.g. ggml-org/llama.cpp). Stage-3 provenance parser already tolerates dots (inconsistent). Fix: change to ([^/\\s]+?) while preserving .git stripping. VERIFY the CURRENT regex in skf-validate-pins.py (line may differ). Check the Stage-3 / provenance regex to confirm the inconsistency claim. Check test/test-skf-validate-pins.py for coverage and whether a dotted-repo test case exists. Also grep for other GitHub-URL regexes in the repo that share the same defect.',
  },
  {
    id: 'brief-scope-keyword', severity: 'friction',
    file: `${GMC}/hc-skf-brief-skill-20260615-064527.md`,
    sources: ['src/shared/scripts/skf-recommend-scope-type.py', 'src/skf-brief-skill/references/scope-definition.md'],
    hint: 'Finding: reference-app-keywords heuristic in skf-recommend-scope-type.py fires on common API nouns (lifecycle/flow/pipeline) and outranks structural rules like specific-modules-count, mis-recommending reference-app. Suggested: require reference-app-keywords to co-occur with a wiring signal (examples/ tree, "example app" phrasing) before outranking structural rules; drop/down-weight high-frequency API nouns. VERIFY the current keyword list, the ladder ordering, and the exact heuristic names in the script. There is test/test-skf-recommend-scope-type.py — check what it asserts so a fix does not break existing expectations, and design added test cases.',
  },
  {
    id: 'create-skill-docrot-dup', severity: 'gap',
    file: `${GMC}/hc-skf-create-skill-20260615-071520.md`,
    sources: ['src/skf-create-skill/references/step-doc-rot.md', 'src/skf-create-skill/references/compile.md'],
    hint: 'Finding: step-doc-rot.md §2 correction-pattern grep matches the compiled SKILL.md own "## Migration & Deprecation Warnings" section (authored by compile §4b from the same T2-future annotations), causing circular ## CORRECTION duplication. Suggested: in §2 exclude correction matches originating inside the SKILL.md own Migration & Deprecation Warnings section (or any §4b line with a [QMD:]/[DOC:] citation). VERIFY current step-doc-rot.md §2 feeders and grep logic; confirm compile §4b authors that section. There is test/test-skf-step-doc-rot.py — check if a script backs this step or if it is pure prose.',
  },
  {
    id: 'stack-body-token-gate', severity: 'bug',
    file: `${GMC}/hc-skf-create-stack-skill-20260615-044100.md`,
    sources: ['src/skf-create-stack-skill/references/generate-output.md', 'src/shared/scripts/skf-validate-frontmatter.py'],
    hint: 'Finding: generate-output.md §8 pre-commit gate treats a skf-validate-frontmatter.py --max-body-tokens 5000 violation (status fail, HIGH body issue) as HALT-to-fix, but authoritative npx skill-check rates body.max_tokens as a non-blocking warn; the char/4 estimate (~11164) roughly doubles skill-check real count (5700). Suggested: align gate so --max-body-tokens violations WARN not HALT, or have the gate use skill-check token counter; keep the body LINE gate (500) as hard. VERIFY: how does skf-validate-frontmatter.py currently classify a --max-body-tokens overflow (severity high/medium/low, status)? How does generate-output.md §8 map that to HALT vs warn? Cross-check the SAME gate wording in other skf skills (create-skill, quick-skill) to see if the fix must be consistent across them. There is test/test-skf-validate-frontmatter.py.',
  },
  {
    id: 'refine-arch-filename', severity: 'gap',
    file: `${GMC}/hc-skf-refine-architecture-20260615-035919.md`,
    sources: ['src/skf-refine-architecture/references/report.md', 'src/skf-refine-architecture/references/compile.md', 'src/skf-refine-architecture/references/init.md', 'src/skf-refine-architecture/SKILL.md'],
    hint: 'Finding: refined-doc outputFile is templated on forge config {project_name}, misnaming the proposal when RA refines an architecture doc belonging to a different project (producer/consumer split). outputFile resolved to refined-architecture-gmc-skills.md for a doc whose own frontmatter is project_name: global-maths-club. Suggested: in init.md/On-Activation, when the loaded architecture doc carries project_name in its YAML frontmatter, prefer it for the outputFile {project_name}, else fall back to config. VERIFY report.md:5 outputFile template, compile.md same template, and init.md/On-Activation project_name resolution. Confirm both report.md and compile.md use the same variable so the fix stays consistent.',
  },
]

phase('Validate & Design')

const results = await pipeline(
  findings,
  (f) => agent(
    `You are re-validating a stale (2-3 week old) SKF workflow-health finding against the CURRENT source tree, then designing a precise, minimal, correct fix. Findings are frequently stale, mis-framed, or already-fixed — be skeptical and verify against real code, never trust the finding's own line numbers.

REPO ROOT: ${REPO}
FINDING FILE (read it in full first): ${f.file}
Finding id: ${f.id} (severity claimed: ${f.severity})
Primary source files to inspect (relative to repo root): ${f.sources.join(', ')}

Analyst hint: ${f.hint}
${CONVENTIONS}

Do this:
1. Read the finding file in full.
2. Read the ACTUAL current source at ${REPO}/<each source>. Locate the real code/prose the finding is about (line numbers will have drifted). Quote what you actually see.
3. Decide the verdict: is the defect STILL present exactly as described, PARTIALLY, ALREADY_FIXED, a FALSE_POSITIVE, or does it NEED_REFRAMING?
4. If it needs fixing, design the minimal correct fix: exact old-text -> new-text snippets (that will literally match the current file), every file that must change together, test additions/updates, and any heading-gate / validate:refs / schema / cross-platform concerns.
5. Assess breaking-change risk honestly — a step-file prose change can break the SKILL.md heading-gate scanner or validate:refs; a script change can break its pytest suite or downstream callers. Grep for other callers/uses of anything you change.

Return ONLY the structured object. Be concrete: a fix I cannot apply verbatim is useless.`,
    { label: `validate:${f.id}`, phase: 'Validate & Design', schema: VALIDATION_SCHEMA },
  ),
  (design, f) => {
    if (!design || (design.verdict !== 'STILL_VALID' && design.verdict !== 'PARTIALLY_VALID' && design.verdict !== 'NEEDS_REFRAMING')) {
      // No fix to verify (already-fixed / false-positive). Pass design through.
      return { design, verify: null }
    }
    return agent(
      `You are an adversarial verifier. A prior analyst re-validated an SKF finding and proposed a fix. Your job is to REFUTE it: find any way the fix is wrong, incomplete, or would break something. Default to skepticism.

REPO ROOT: ${REPO}
Finding id: ${f.id}
Source files: ${f.sources.join(', ')}
${CONVENTIONS}

The analyst's verdict + proposed fix (JSON):
${JSON.stringify(design, null, 2)}

Independently:
1. Re-read the relevant CURRENT source yourself — do not trust the analyst's quotes.
2. Verify the proposed old-text snippets actually exist verbatim in the files (an edit that will not match is a defect — flag it).
3. Check the fix does not break: the SKILL.md heading-gate scanner, validate:refs prose resolution, the script's pytest suite, or any other caller (grep for uses of the changed symbol/pattern/probe-order across the whole repo).
4. Check the fix is COMPLETE: are there sibling files with the identical defect the analyst missed (e.g. the same probe-order block or gate wording duplicated in other skf skills)? Are there tests that must be added or updated?
5. Give the final recommendation.

Return ONLY the structured object.`,
      { label: `verify:${f.id}`, phase: 'Adversarial Verify', schema: VERIFY_SCHEMA },
    ).then((verify) => ({ design, verify }))
  },
)

return results.filter(Boolean)

